function rewriteExactPoisonPhysicalInventoryFixtureV1(root: string, original: ExactOriginalPoisonStoreFixtureV1): void {
  const modulePath = path.join(root, "src/internal-production/baseline-post-handoff-receipt-v1.ts");
  let source = readFileSync(modulePath, "utf8");
  const inventoryLiteral = `const EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1 = "${EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1}";`;
  assert.equal(source.split(inventoryLiteral).length - 1, 1, "production must retain one private frozen inventory-hash literal");
  source = source.replace(inventoryLiteral, `const EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1 = "${original.inventoryHash}";`);
  const identityLiteral = /const EXACT_POISON_PREDECESSOR_FILE_IDENTITIES_V1 = Object\.freeze\(\[[\s\S]*?\]\s+as const\);/;
  assert.equal((source.match(identityLiteral) ?? []).length, 1, "production must retain one private frozen predecessor-identity literal");
  source = source.replace(
    identityLiteral,
    `const EXACT_POISON_PREDECESSOR_FILE_IDENTITIES_V1 = Object.freeze(${JSON.stringify(original.predecessorFileIdentities)} as const);`,
  );
  writeFileSync(modulePath, source);
}

function instrumentExactPoisonPublisherCoreFixtureV1(
  root: string,
  original: ExactOriginalPoisonStoreFixtureV1,
  fault: string | null,
  inventoryAlreadyRewritten = false,
): void {
  if (!inventoryAlreadyRewritten) rewriteExactPoisonPhysicalInventoryFixtureV1(root, original);
  const modulePath = path.join(root, "src/internal-production/baseline-post-handoff-receipt-v1.ts");
  let source = readFileSync(modulePath, "utf8");
  if (fault === "inventory-hash-drift") {
    const literal = `const EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1 = "${original.inventoryHash}";`;
    assert.equal(source.split(literal).length - 1, 1);
    source = source.replace(literal, `const EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1 = "${"f".repeat(64)}";`);
  }
  if (fault === "fingerprint-drift") {
    const literal = `const EXACT_POISON_CONTAMINATION_FINGERPRINT_HASH_V1 = "${EXACT_POISON_CONTAMINATION_FINGERPRINT_HASH_V1}";`;
    assert.equal(source.split(literal).length - 1, 1);
    source = source.replace(literal, `const EXACT_POISON_CONTAMINATION_FINGERPRINT_HASH_V1 = "${"f".repeat(64)}";`);
  }
  const coreMarker = "async function resumeExactPoisonQuarantinePublisherCoreV1(): Promise<void> {";
  assert.equal(source.split(coreMarker).length - 1, 1, "production must retain one private zero-input publisher core");
  source = source.replace(coreMarker, `export ${coreMarker}`);
  const admissionMarker = "async function observeExactPoisonQuarantineAdmissionV1(";
  assert.equal(source.split(admissionMarker).length - 1, 1, "production must retain one private exact-poison admission boundary");
  const admissionStart = source.indexOf(admissionMarker);
  const admissionEnd = source.indexOf(`export ${coreMarker}`, admissionStart);
  assert.ok(admissionStart >= 0 && admissionEnd > admissionStart, "the private admission boundary must precede the publisher core");
  const noWriteMarker = "async function observeExactPoisonRecoveryCandidatesNoWriteV1(";
  const noWriteStart = source.indexOf(noWriteMarker);
  const rawStart = noWriteStart >= 0 ? noWriteStart : admissionStart;
  const rawEnd = noWriteStart >= 0 ? admissionStart : admissionEnd;
  assert.ok(rawEnd > rawStart, "the raw no-write observations have one bounded lower/admission region");
  let admissionRegion = source.slice(rawStart, rawEnd);
  for (const observer of [
    "observeExactPoisonSyntheticGitObjectAbsenceV1",
    "observeExactPoisonRecoveryCurrentPrerequisitesNoWriteV1",
    "observeCurrentInternalProductionCleanSetfarmSourceBuildV1",
    "observeCurrentPba",
    "observeInternalProductionServiceCensusV1",
    "observePhysicalInventoryV1",
    "observeLegacyDatabaseCensusV1",
    "observePhaseClosedZeroV1",
    "observeExactPoisonRecoveryDownstreamAbsenceNoWriteV1",
  ]) assert.ok(admissionRegion.includes(observer), `the private admission boundary must call ${observer}`);
  const probe = '(Reflect.get(globalThis,"__p4ExactPoisonPublisherAdmissionV1") as {next:(kind:string)=>unknown;nextPhysical:(...args:unknown[])=>unknown;nextPhase:(...args:unknown[])=>unknown;observeSyntheticGit:(...args:unknown[])=>unknown})';
  const rawCalls = Object.freeze([
    Object.freeze({ source: "observeCurrentInternalProductionCleanSetfarmSourceBuildV1()", target: `${probe}.next("source")` }),
    Object.freeze({ source: "observeCurrentPba()", target: `${probe}.next("pba")` }),
    Object.freeze({ source: "observeExactPoisonRecoveryCurrentPrerequisitesNoWriteV1()", target: `${probe}.next("prerequisites")` }),
    Object.freeze({ source: "observeInternalProductionServiceCensusV1()", target: `${probe}.next("service")` }),
    Object.freeze({ source: "observeLegacyDatabaseCensusV1()", target: `${probe}.next("database")` }),
    Object.freeze({ source: "observePhysicalInventoryV1(", target: `${probe}.nextPhysical(` }),
    Object.freeze({ source: "observePhaseClosedZeroV1(", target: `${probe}.nextPhase(` }),
    Object.freeze({ source: "observeExactPoisonRecoveryDownstreamAbsenceNoWriteV1()", target: `${probe}.next("downstream")` }),
    Object.freeze({ source: "observeExactPoisonSyntheticGitObjectAbsenceV1(", target: `${probe}.observeSyntheticGit(` }),
  ]);
  for (const rawCall of rawCalls) {
    assert.ok(admissionRegion.includes(rawCall.source), `the private admission boundary must directly invoke ${rawCall.source}`);
    admissionRegion = admissionRegion.replaceAll(rawCall.source, rawCall.target);
  }
  source = source.slice(0, rawStart) + admissionRegion + source.slice(rawEnd);
  const admissionCall = "await observeExactPoisonQuarantineAdmissionV1(operation, heldWriter)";
  assert.ok(source.includes(admissionCall), "publisher core must call the private admission boundary with only its strict operation and held writer");
  const countedAdmission = 'await (()=>{const probe=Reflect.get(globalThis,"__p4ExactPoisonPublisherAdmissionV1") as undefined|{admissionCalls:number};if(!probe)throw new Error("P4_EXACT_POISON_ADMISSION_PROBE_MISSING");probe.admissionCalls+=1;return observeExactPoisonQuarantineAdmissionV1(operation,heldWriter)})()';
  source = source.replaceAll(admissionCall, countedAdmission);
  writeFileSync(modulePath, source);
}

function instrumentExactPoisonRecoveryLeafFixtureV1(
  root: string,
  fault: ExactPoisonRecoveryLeafFaultFixtureV1 | null,
): void {
  const modulePath = path.join(root, "src/internal-production/baseline-post-handoff-receipt-v1.ts");
  let source = readFileSync(modulePath, "utf8");
  const leafMarker = "async function publishExactPoisonRecoveryCandidateV1(";
  const coreMarker = "\nasync function resumeExactPoisonQuarantinePublisherCoreV1(): Promise<void> {";
  assert.equal(source.split(leafMarker).length - 1, 1, "production must retain one private held-writer exact-poison recovery leaf");
  const leafStart = source.indexOf(leafMarker);
  const leafEnd = source.indexOf(coreMarker, leafStart);
  assert.ok(leafStart >= 0 && leafEnd > leafStart, "the private recovery leaf must immediately precede the publisher core");
  let leaf = source.slice(leafStart, leafEnd);
  for (const literal of [
    "operation: FileSnapshot",
    "admitted: ExactPoisonQuarantineAdmissionV1",
    "phase: ExactPoisonRecoveryPublicationPhaseV1",
    "ordinal: 0 | 1 | 2 | 3 | 4 | 5 | 6",
    "heldWriter: ExactPoisonRecoveryWriterV1",
    "const candidate = admitted.candidates[ordinal]",
  ]) assert.ok(leaf.includes(literal), `the exact-poison recovery leaf must retain ${literal}`);
  assert.doesNotMatch(leaf, /publishLegacyZeroRecordV1|nonselected/i, "the recovery leaf must not inherit the generic publisher or nonselected-temp cleanup");
  const coreEnd = source.indexOf("\nasync function resumeExactPoisonQuarantineBeforeSelectionV1()", leafEnd);
  assert.ok(coreEnd > leafEnd, "the publisher core must have a stable copied-module boundary");
  const core = source.slice(leafEnd, coreEnd);
  assert.equal(
    core.split("await publishExactPoisonRecoveryCandidateV1(operation, admission, phase, ordinal, heldWriter);").length - 1,
    1,
    "the core must call the private recovery leaf once from its exact phase/ordinal loop",
  );
  assert.doesNotMatch(core, /publishLegacyZeroRecordV1\(candidate\.target/, "the core must not bypass the recovery-specific leaf");

  const bodyMarker = "): Promise<void> {";
  const bodyOffset = leaf.indexOf(bodyMarker);
  assert.ok(bodyOffset >= 0, "the exact-poison recovery leaf must have one async void body");
  const hook = `\n  const P4_EXACT_POISON_RECOVERY_LEAF_FAULT_V1 = ${JSON.stringify(fault)} as null | Readonly<{ phase: string; ordinal: number; boundary: string; occurrence: number }>;\n  let p4ExactPoisonRecoveryLeafMatchCountV1 = 0;\n  const p4ExactPoisonRecoveryLeafBoundaryV1 = (boundary: "temp-create" | "partial-write" | "complete-write" | "fchmod" | "file-fsync" | "close" | "link" | "parent-fsync" | "incomplete-unlink" | "selected-unlink" | "final-reopen"): void => {\n    const event = Object.freeze({ phase, ordinal, boundary });\n    const expected = P4_EXACT_POISON_RECOVERY_LEAF_FAULT_V1;\n    if (expected === null || event.phase !== expected.phase || event.ordinal !== expected.ordinal || event.boundary !== expected.boundary) return;\n    p4ExactPoisonRecoveryLeafMatchCountV1 += 1;\n    if (p4ExactPoisonRecoveryLeafMatchCountV1 === expected.occurrence) throw new Error(\`P4_EXACT_POISON_RECOVERY_LEAF_FAULT:\${event.phase}:\${event.boundary}:\${p4ExactPoisonRecoveryLeafMatchCountV1}\`);\n  };`;
  leaf = leaf.slice(0, bodyOffset + bodyMarker.length) + hook + leaf.slice(bodyOffset + bodyMarker.length);
  const replaceOnce = (literal: string, replacement: string, label: string): void => {
    assert.equal(leaf.split(literal).length - 1, 1, `the exact-poison recovery leaf must expose one ${label} boundary`);
    leaf = leaf.replace(literal, replacement);
  };
  replaceOnce(
    "tempDescriptor = openSync(temp, constants.O_CREAT | constants.O_EXCL | constants.O_RDWR | constants.O_NOFOLLOW, 0o600);",
    "tempDescriptor = openSync(temp, constants.O_CREAT | constants.O_EXCL | constants.O_RDWR | constants.O_NOFOLLOW, 0o600); p4ExactPoisonRecoveryLeafBoundaryV1(\"temp-create\");",
    "O_EXCL temp-create",
  );
  replaceOnce(
    "writeFileSync(tempDescriptor, candidate.bytes);",
    "writeFileSync(tempDescriptor, candidate.bytes.subarray(0, Math.max(1, Math.floor(candidate.bytes.length / 2)))); p4ExactPoisonRecoveryLeafBoundaryV1(\"partial-write\"); writeFileSync(temp, candidate.bytes); p4ExactPoisonRecoveryLeafBoundaryV1(\"complete-write\");",
    "partial/full write",
  );
  replaceOnce(
    "fchmodSync(tempDescriptor, 0o600);",
    "fchmodSync(tempDescriptor, 0o600); p4ExactPoisonRecoveryLeafBoundaryV1(\"fchmod\");",
    "fchmod",
  );
  replaceOnce(
    "fsyncSync(tempDescriptor);",
    "fsyncSync(tempDescriptor); p4ExactPoisonRecoveryLeafBoundaryV1(\"file-fsync\");",
    "file fsync",
  );
  replaceOnce(
    "closeSync(tempDescriptor);\n    tempDescriptor = -1;",
    "closeSync(tempDescriptor);\n    tempDescriptor = -1; p4ExactPoisonRecoveryLeafBoundaryV1(\"close\");",
    "temp close and closed-descriptor sentinel",
  );
  replaceOnce(
    "linkSync(temp, candidate.target);",
    "linkSync(temp, candidate.target); p4ExactPoisonRecoveryLeafBoundaryV1(\"link\");",
    "no-replace link",
  );
  const guardedPathParentFsync = "heldWriter.assertStable(); fsyncCurrentEntryDirectory(directory); heldWriter.assertStable();";
  const pinnedParentFsync = "fsyncExactPoisonRecoveryCandidateParentV1(heldWriter, directory);";
  const guardedPathCount = leaf.split(guardedPathParentFsync).length - 1;
  const pinnedCount = leaf.split(pinnedParentFsync).length - 1;
  assert.equal(guardedPathCount === 0 || pinnedCount === 0, true, "the recovery leaf must use one exact parent-fsync authority");
  assert.ok(guardedPathCount + pinnedCount >= 3, "the exact-poison recovery leaf must fsync its parent after cleanup, publication, and adoption");
  if (guardedPathCount > 0) {
    leaf = leaf.replaceAll(guardedPathParentFsync, `${guardedPathParentFsync} p4ExactPoisonRecoveryLeafBoundaryV1("parent-fsync");`);
  } else {
    leaf = leaf.replaceAll(pinnedParentFsync, `${pinnedParentFsync} p4ExactPoisonRecoveryLeafBoundaryV1("parent-fsync");`);
  }
  const unlinkParts = leaf.split("unlinkSync(temp);");
  assert.equal(unlinkParts.length - 1, 2, "the recovery leaf must have only incomplete-temp and selected-temp unlink sites");
  leaf = `${unlinkParts[0]}unlinkSync(temp); p4ExactPoisonRecoveryLeafBoundaryV1("incomplete-unlink");${unlinkParts[1]}unlinkSync(temp); p4ExactPoisonRecoveryLeafBoundaryV1("selected-unlink");${unlinkParts[2]}`;
  assert.equal((leaf.match(/unlinkSync\(/g) ?? []).length, 2, "the recovery leaf must never unlink a nonselected recovery-family member");
  const reopenStart = leaf.lastIndexOf("readTask12ReceiptStoreSnapshotV1(candidate.target");
  assert.ok(reopenStart >= 0, "the recovery leaf must finish with one strict final reopen");
  const reopenEnd = leaf.indexOf(";", reopenStart);
  assert.ok(reopenEnd > reopenStart, "the strict final reopen must be a complete statement");
  leaf = leaf.slice(0, reopenEnd + 1) + ' p4ExactPoisonRecoveryLeafBoundaryV1("final-reopen");' + leaf.slice(reopenEnd + 1);
  source = source.slice(0, leafStart) + leaf + source.slice(leafEnd);
  writeFileSync(modulePath, source);
}

function setExactPoisonRecoveryLeafFaultFixtureV1(
  root: string,
  fault: ExactPoisonRecoveryLeafFaultFixtureV1 | null,
): void {
  const modulePath = path.join(root, "src/internal-production/baseline-post-handoff-receipt-v1.ts");
  const source = readFileSync(modulePath, "utf8");
  const literal = /const P4_EXACT_POISON_RECOVERY_LEAF_FAULT_V1 = .*? as null \| Readonly<\{ phase: string; ordinal: number; boundary: string; occurrence: number \}>;/;
  assert.equal((source.match(literal) ?? []).length, 1, "the copied recovery leaf must retain one private literal-only fault configuration");
  writeFileSync(
    modulePath,
    source.replace(
      literal,
      `const P4_EXACT_POISON_RECOVERY_LEAF_FAULT_V1 = ${JSON.stringify(fault)} as null | Readonly<{ phase: string; ordinal: number; boundary: string; occurrence: number }>;`,
    ),
  );
}

function fixtureTransportValueV1(value: unknown): unknown {
  if (Buffer.isBuffer(value)) return Object.freeze({ __p4ExactBufferBase64V1: value.toString("base64") });
  if (Array.isArray(value)) return value.map((entry) => fixtureTransportValueV1(entry));
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, entry]) => [key, fixtureTransportValueV1(entry)]));
  }
  return value;
}

function runExactPoisonPublisherCoreFixtureV1(
  root: string,
  observations: Readonly<Record<string, readonly unknown[]>>,
  gitFault: "error" | null,
): ReturnType<typeof spawnSync> {
  const transported = JSON.stringify(fixtureTransportValueV1(observations));
  const transportPath = path.join(path.dirname(root), ".p4-exact-poison-admission.json");
  fixtureFile(path.dirname(root), ".p4-exact-poison-admission.json", `${transported}\n`, 0o600);
  return runFixtureExpression(root, `(async()=>{const {readFileSync}=await import("node:fs");const revive=(value)=>{if(Array.isArray(value))return value.map(revive);if(value&&typeof value==="object"){if(Object.keys(value).length===1&&typeof value.__p4ExactBufferBase64V1==="string")return Buffer.from(value.__p4ExactBufferBase64V1,"base64");return Object.fromEntries(Object.entries(value).map(([key,entry])=>[key,revive(entry)]))}return value};const values=revive(JSON.parse(readFileSync(${JSON.stringify(transportPath)},"utf8")));const cursors={};const next=(kind)=>{const sequence=values[kind];if(!Array.isArray(sequence)||sequence.length===0)throw new Error("P4_EXACT_POISON_RAW_SEQUENCE_MISSING:"+kind);const cursor=cursors[kind]??0;cursors[kind]=cursor+1;return sequence[cursor%sequence.length]};const probe={admissionCalls:0,cursors,next,nextPhysical:(..._args)=>next("physical"),nextPhase:(..._args)=>next("phase"),observeSyntheticGit:(..._args)=>{const fault=${JSON.stringify(gitFault)};if(fault!==null)throw new Error("P4_EXACT_POISON_SYNTHETIC_GIT_"+fault.toUpperCase());return next("syntheticGit")}};Reflect.set(globalThis,"__p4ExactPoisonPublisherAdmissionV1",probe);let outcome="returned",message=null;try{await m.resumeExactPoisonQuarantinePublisherCoreV1()}catch(error){outcome="threw";message=String(error)}process.stdout.write(JSON.stringify({outcome,message,admissionCalls:probe.admissionCalls,cursors:probe.cursors}))})()`);
}

function assertExactPoisonPublishedRecordV1(store: string, record: ExactPoisonStrictChainRecordV1, label: string): void {
  const target = path.join(store, record.locator);
  const stats = lstatSync(target);
  assert.equal(stats.isFile(), true, `${label} must be a regular file`);
  assert.equal(stats.isSymbolicLink(), false, `${label} must not be a symlink`);
  assert.equal(stats.mode & 0o7777, 0o600, `${label} mode`);
  assert.equal(stats.nlink, 1, `${label} link count`);
  assert.equal(readFileSync(target).equals(record.bytes), true, `${label} bytes`);
  for (let directory = path.dirname(target); directory !== store; directory = path.dirname(directory)) {
    const directoryStats = lstatSync(directory);
    assert.equal(directoryStats.isDirectory(), true, `${label} parent must be a directory`);
    assert.equal(directoryStats.isSymbolicLink(), false, `${label} parent must not be a symlink`);
    assert.equal(directoryStats.mode & 0o7777, 0o700, `${label} parent mode`);
  }
}

function recoveryPhaseSnapshotV1(store: string, originalLocators: readonly string[]): readonly Readonly<Record<string, string | number>>[] {
  const originals = new Set(originalLocators);
  const recoveryPrefixes = [
    "records/current-entry-store-quarantine-dispositions",
    "records/current-entry-store-successor-edges",
    "records/current-entry-store-successor-activation-seals",
    "records/current-entry-store-successor-activation-commits",
    "stores",
  ];
  return Object.freeze(filesystemTreeSnapshot(store).filter((entry) => {
    const locator = String(entry.locator);
    if (originals.has(locator)) return false;
    return recoveryPrefixes.some((prefix) => locator === prefix || locator.startsWith(`${prefix}/`))
      || locator.includes("current-entry-store-quarantine-recovery-by-predecessor-operation");
  }));
}

function exactPoisonRecoveryFinalLocatorsV1(chain: ExactPoisonStrictChainFixtureV1): readonly string[] {
  const locators = new Set<string>();
  for (const record of [
    chain.records.disposition,
    chain.records.successorOperation,
    chain.records.successorAuthorityV31,
    chain.records.successorPending,
    chain.records.edge,
    chain.records.seal,
    chain.records.commit,
  ]) {
    locators.add(record.locator);
    for (let parent = path.posix.dirname(record.locator); parent !== "." && parent !== "records"; parent = path.posix.dirname(parent)) {
      locators.add(parent);
    }
  }
  return Object.freeze([...locators].sort());
}

function exactPoisonRecoveryPhaseRecordV1(
  chain: ExactPoisonStrictChainFixtureV1,
  phase: ExactPoisonRecoveryPublicationPhaseFixtureV1,
): ExactPoisonStrictChainRecordV1 {
  return chain.records[phase.record];
}

function exactPoisonRecoveryTempPathV1(target: string, index = 0): string {
  const uuid = EXACT_POISON_RECOVERY_TEMP_UUIDS_V1[index];
  assert.notEqual(uuid, undefined, "the recovery temp fixture index must remain within the explicit cap fixtures");
  return path.join(path.dirname(target), `.${path.basename(target)}.${uuid}.tmp`);
}

function seedExactPoisonRecoveryPredecessorPhasesV1(
  original: ExactOriginalPoisonStoreFixtureV1,
  chain: ExactPoisonStrictChainFixtureV1,
  ordinal: ExactPoisonRecoveryPublicationPhaseFixtureV1["ordinal"],
): void {
  for (const phase of EXACT_POISON_RECOVERY_PUBLICATION_PHASES_V1.slice(0, ordinal)) {
    const record = exactPoisonRecoveryPhaseRecordV1(chain, phase);
    writeStrictCurrentEntryFixtureRecordV1(original.store, record.locator, record.bytes);
  }
}

function assertExactPoisonRecoveryBoundaryFrontierV1(
  original: ExactOriginalPoisonStoreFixtureV1,
  chain: ExactPoisonStrictChainFixtureV1,
  phase: ExactPoisonRecoveryPublicationPhaseFixtureV1,
  boundary: ExactPoisonRecoveryLeafBoundaryFixtureV1,
  state: "fresh-publication" | "incomplete-cleanup" | "one-link-durability" = "fresh-publication",
): void {
  const expectedLocators = new Set<string>();
  const addParents = (locator: string): void => {
    for (let parent = path.posix.dirname(locator); parent !== "." && parent !== "records"; parent = path.posix.dirname(parent)) {
      expectedLocators.add(parent);
    }
  };
  for (const prior of EXACT_POISON_RECOVERY_PUBLICATION_PHASES_V1.slice(0, phase.ordinal)) {
    const record = exactPoisonRecoveryPhaseRecordV1(chain, prior);
    addParents(record.locator);
    expectedLocators.add(record.locator);
    assertExactPoisonPublishedRecordV1(original.store, record, `${phase.phase}/${boundary}:prior:${prior.phase}`);
  }
  const record = exactPoisonRecoveryPhaseRecordV1(chain, phase);
  addParents(record.locator);
  const target = path.join(original.store, record.locator);
  const temp = exactPoisonRecoveryTempPathV1(target);
  const tempLocator = path.relative(original.store, temp).split(path.sep).join("/");
  const tempPresent = state === "fresh-publication" && !["selected-unlink", "final-reopen"].includes(boundary);
  const finalPresent = state === "one-link-durability"
    || (state === "fresh-publication" && ["link", "parent-fsync", "selected-unlink", "final-reopen"].includes(boundary));
  if (tempPresent) expectedLocators.add(tempLocator);
  if (finalPresent) expectedLocators.add(record.locator);
  assert.equal(existsSync(temp), tempPresent, `${phase.phase}/${boundary}: exact current temp presence`);
  assert.equal(existsSync(target), finalPresent, `${phase.phase}/${boundary}: exact current final presence`);
  if (tempPresent) {
    const stats = lstatSync(temp);
    const expectedBytes = boundary === "temp-create"
      ? Buffer.alloc(0)
      : boundary === "partial-write"
        ? record.bytes.subarray(0, Math.max(1, Math.floor(record.bytes.length / 2)))
        : record.bytes;
    assert.equal(stats.isFile(), true, `${phase.phase}/${boundary}: temp regular file`);
    assert.equal(stats.mode & 0o7777, 0o600, `${phase.phase}/${boundary}: temp mode`);
    assert.equal(readFileSync(temp).equals(expectedBytes), true, `${phase.phase}/${boundary}: temp bytes`);
    assert.equal(stats.nlink, finalPresent ? 2 : 1, `${phase.phase}/${boundary}: temp link count`);
  }
  if (finalPresent) {
    const stats = lstatSync(target);
    assert.equal(stats.isFile(), true, `${phase.phase}/${boundary}: final regular file`);
    assert.equal(stats.mode & 0o7777, 0o600, `${phase.phase}/${boundary}: final mode`);
    assert.equal(stats.nlink, tempPresent ? 2 : 1, `${phase.phase}/${boundary}: final link count`);
    assert.equal(readFileSync(target).equals(record.bytes), true, `${phase.phase}/${boundary}: final bytes`);
    if (tempPresent) assert.equal(lstatSync(temp).ino, stats.ino, `${phase.phase}/${boundary}: selected temp and final inode`);
  }
  const actualLocators = recoveryPhaseSnapshotV1(original.store, original.originalLocators)
    .map((entry) => String(entry.locator))
    .sort();
  assert.deepEqual(actualLocators, [...expectedLocators].sort(), `${phase.phase}/${boundary}: exact prior/current frontier and zero later prefixes`);
  for (const later of EXACT_POISON_RECOVERY_PUBLICATION_PHASES_V1.slice(phase.ordinal + 1)) {
    assert.equal(
      existsSync(path.join(original.store, exactPoisonRecoveryPhaseRecordV1(chain, later).locator)),
      false,
      `${phase.phase}/${boundary}: later ${later.phase} final must remain absent`,
    );
  }
}

type ExactPoisonRecoveryLeafStateFixtureV1 =
  | "F-1-incomplete"
  | "F-1-noncanonical"
  | "F0-equal"
  | "F1-F2-selected-nlink2"
  | "F2u-F3-F4-final-nlink1";

function seedExactPoisonRecoveryLeafStateV1(
  original: ExactOriginalPoisonStoreFixtureV1,
  chain: ExactPoisonStrictChainFixtureV1,
  phase: ExactPoisonRecoveryPublicationPhaseFixtureV1,
  state: ExactPoisonRecoveryLeafStateFixtureV1,
): Readonly<{ target: string; temp: string }> {
  seedExactPoisonRecoveryPredecessorPhasesV1(original, chain, phase.ordinal);
  const record = exactPoisonRecoveryPhaseRecordV1(chain, phase);
  const target = path.join(original.store, record.locator);
  const temp = exactPoisonRecoveryTempPathV1(target);
  if (state === "F2u-F3-F4-final-nlink1") {
    writeStrictCurrentEntryFixtureRecordV1(original.store, record.locator, record.bytes);
    return Object.freeze({ target, temp });
  }
  const tempBytes = state === "F-1-incomplete"
    ? record.bytes.subarray(0, Math.max(1, Math.floor(record.bytes.length / 2)))
    : state === "F-1-noncanonical"
      ? Buffer.from("{}\n", "utf8")
      : record.bytes;
  writeStrictCurrentEntryFixtureRecordV1(original.store, path.relative(original.store, temp), tempBytes);
  if (state === "F1-F2-selected-nlink2") linkSync(temp, target);
  return Object.freeze({ target, temp });
}

type ExactPoisonRecoveryLeafInvalidFixtureV1 =
  | "unequal-temp"
  | "crossed-temp"
  | "two-incomplete-temps"
  | "two-equal-temps"
  | "eight-equal-temps"
  | "nine-equal-temps"
  | "unknown-member"
  | "wrong-temp-mode"
  | "wrong-temp-link-count"
  | "temp-symlink"
  | "final-plus-temp"
  | "final-plus-incomplete-temp"
  | "unequal-final"
  | "wrong-final-mode"
  | "wrong-final-link-count"
  | "final-symlink";

const EXACT_POISON_RECOVERY_LEAF_INVALID_FIXTURES_V1 = Object.freeze([
  "two-incomplete-temps",
  "two-equal-temps",
  "eight-equal-temps",
  "nine-equal-temps",
  "unknown-member",
  "wrong-temp-mode",
  "wrong-temp-link-count",
  "temp-symlink",
  "final-plus-temp",
  "final-plus-incomplete-temp",
  "unequal-final",
  "wrong-final-mode",
  "wrong-final-link-count",
  "final-symlink",
] as const satisfies readonly ExactPoisonRecoveryLeafInvalidFixtureV1[]);

function exactPoisonRecoveryStrictUnequalBytesV1(
  record: ExactPoisonStrictChainRecordV1,
  phase: ExactPoisonRecoveryPublicationPhaseFixtureV1,
  kind: "unequal-temp" | "crossed-temp",
): Buffer {
  const shape = {
    disposition: Object.freeze({ refKey: "dispositionRef", hashKey: "dispositionHash", prefix: "setfarm://internal-production/current-entry-store-quarantine-disposition/sha256/" }),
    "successor-authority-v31": Object.freeze({ refKey: "authorityV3Migration31AuditRef", hashKey: "authorityV3Migration31AuditHash", prefix: "setfarm://internal-production/authority-v3-migration31-audit/sha256/" }),
    "successor-pending": Object.freeze({ refKey: "pendingBootstrapHandoffMigrationRef", hashKey: "pendingBootstrapHandoffMigrationHash", prefix: "setfarm://internal-production/pending-bootstrap-handoff-migration/sha256/" }),
    "successor-operation": Object.freeze({ refKey: "operationRef", hashKey: "operationHash", prefix: "setfarm://internal-production/current-entry-operation/sha256/" }),
    "successor-edge": Object.freeze({ refKey: "edgeRef", hashKey: "edgeHash", prefix: "setfarm://internal-production/current-entry-store-successor-edge/sha256/" }),
    "successor-activation-seal": Object.freeze({ refKey: "activationSealRef", hashKey: "activationSealHash", prefix: "setfarm://internal-production/current-entry-store-successor-activation-seal/sha256/" }),
    "successor-activation-commit": Object.freeze({ refKey: "activationCommitRef", hashKey: "activationCommitHash", prefix: "setfarm://internal-production/current-entry-store-successor-activation-commit/sha256/" }),
  }[phase.phase];
  const changed = rehashFixtureRecordV1(record.value, shape.refKey, shape.hashKey, shape.prefix, (core) => {
    if (phase.phase === "disposition") {
      if (kind === "crossed-temp") {
        core.predecessorOperation = Object.freeze({
          operationRef: `setfarm://internal-production/current-entry-operation/sha256/${"f".repeat(64)}`,
          operationHash: "f".repeat(64),
        });
      } else {
        const quarantinedInventory = structuredClone(core.quarantinedInventory as Record<string, unknown>);
        const inventoryBody = structuredClone(quarantinedInventory.inventoryBody as Record<string, unknown>);
        inventoryBody.storeLocator = `${String(inventoryBody.storeLocator)}-strict-unequal`;
        core.quarantinedInventory = Object.freeze({ inventoryBody: Object.freeze(inventoryBody), inventoryHash: canonicalHash(inventoryBody) });
      }
      return;
    }
    if (phase.phase === "successor-authority-v31") {
      const controllerSource = structuredClone(core.controllerSource as Record<string, unknown>);
      controllerSource.buildHash = kind === "unequal-temp" ? "b".repeat(64) : "c".repeat(64);
      core.controllerSource = Object.freeze(controllerSource);
      return;
    }
    if (phase.phase === "successor-pending") {
      if (kind === "unequal-temp") {
        const controllerSource = structuredClone(core.controllerSource as Record<string, unknown>);
        controllerSource.buildHash = "b".repeat(64);
        core.controllerSource = Object.freeze(controllerSource);
      } else {
        const migrationImplementation = structuredClone(core.migrationImplementation as Record<string, unknown>);
        migrationImplementation.gitBlobHash = "f".repeat(40);
        core.migrationImplementation = Object.freeze(migrationImplementation);
      }
      return;
    }
    if (phase.phase === "successor-operation") {
      if (kind === "unequal-temp") {
        const controllerSource = structuredClone(core.controllerSource as Record<string, unknown>);
        controllerSource.buildHash = "b".repeat(64);
        core.controllerSource = Object.freeze(controllerSource);
      } else {
        core.authorityV3Migration31Audit = Object.freeze({
          authorityV3Migration31AuditRef: `setfarm://internal-production/authority-v3-migration31-audit/sha256/${"f".repeat(64)}`,
          authorityV3Migration31AuditHash: "f".repeat(64),
        });
      }
      return;
    }
    if (phase.phase === "successor-edge") {
      if (kind === "unequal-temp") {
        core.successorStoreHash = "f".repeat(64);
        core.successorStoreRelativeRoot = `stores/sha256/ff/${"f".repeat(64)}`;
      } else {
        core.predecessorOperation = Object.freeze({
          operationRef: `setfarm://internal-production/current-entry-operation/sha256/${"f".repeat(64)}`,
          operationHash: "f".repeat(64),
        });
      }
      return;
    }
    if (phase.phase === "successor-activation-seal") {
      if (kind === "unequal-temp") core.completeZeroEffectBracketHash = "f".repeat(64);
      else core.successorEdge = Object.freeze({ edgeRef: `setfarm://internal-production/current-entry-store-successor-edge/sha256/${"f".repeat(64)}`, edgeHash: "f".repeat(64) });
      return;
    }
    if (kind === "unequal-temp") core.postSealCompleteZeroEffectBracketHash = "f".repeat(64);
    else core.successorActivationSeal = Object.freeze({ activationSealRef: `setfarm://internal-production/current-entry-store-successor-activation-seal/sha256/${"f".repeat(64)}`, activationSealHash: "f".repeat(64) });
  });
  assert.deepEqual(Object.keys(changed.value).sort(), Object.keys(record.value).sort(), `${phase.phase}/${kind}: exact wrapper key set`);
  assert.equal(changed.bytes.toString("utf8"), `${canonical(changed.value)}\n`, `${phase.phase}/${kind}: canonical wrapper plus LF`);
  assert.notEqual(changed.bytes.equals(record.bytes), true, `${phase.phase}/${kind}: strict current-family bytes must compete with the admitted candidate`);
  return changed.bytes;
}

function seedExactPoisonRecoveryInvalidLeafStateV1(
  original: ExactOriginalPoisonStoreFixtureV1,
  chain: ExactPoisonStrictChainFixtureV1,
  phase: ExactPoisonRecoveryPublicationPhaseFixtureV1,
  fault: ExactPoisonRecoveryLeafInvalidFixtureV1,
): void {
  seedExactPoisonRecoveryPredecessorPhasesV1(original, chain, phase.ordinal);
  const record = exactPoisonRecoveryPhaseRecordV1(chain, phase);
  const target = path.join(original.store, record.locator);
  const temp = exactPoisonRecoveryTempPathV1(target);
  const relative = (member: string): string => path.relative(original.store, member);
  const writeTemp = (index: number, bytes: Buffer, mode = 0o600): string => {
    const member = exactPoisonRecoveryTempPathV1(target, index);
    writeStrictCurrentEntryFixtureRecordV1(original.store, relative(member), bytes);
    chmodSync(member, mode);
    return member;
  };
  const incomplete = record.bytes.subarray(0, Math.max(1, Math.floor(record.bytes.length / 2)));
  if (fault === "unequal-temp") {
    writeTemp(0, exactPoisonRecoveryStrictUnequalBytesV1(record, phase, fault));
    return;
  }
  if (fault === "crossed-temp") {
    writeTemp(0, exactPoisonRecoveryStrictUnequalBytesV1(record, phase, fault));
    return;
  }
  if (fault === "two-incomplete-temps") {
    writeTemp(0, incomplete);
    writeTemp(1, incomplete.subarray(0, Math.max(1, Math.floor(incomplete.length / 2))));
    return;
  }
  if (fault === "two-equal-temps" || fault === "eight-equal-temps" || fault === "nine-equal-temps") {
    const count = fault === "two-equal-temps" ? 2 : fault === "eight-equal-temps" ? 8 : 9;
    for (let index = 0; index < count; index += 1) writeTemp(index, record.bytes);
    return;
  }
  if (fault === "unknown-member") {
    writeTemp(0, record.bytes);
    writeStrictCurrentEntryFixtureRecordV1(original.store, relative(path.join(path.dirname(target), ".unexpected-recovery-member")), Buffer.from("unexpected\n", "utf8"));
    return;
  }
  if (fault === "wrong-temp-mode") {
    writeTemp(0, record.bytes, 0o644);
    return;
  }
  if (fault === "wrong-temp-link-count") {
    writeTemp(0, record.bytes);
    linkSync(temp, `${temp}.alias`);
    return;
  }
  if (fault === "temp-symlink") {
    writeStrictCurrentEntryFixtureRecordV1(original.store, relative(path.join(path.dirname(target), ".symlink-source")), record.bytes);
    symlinkSync(".symlink-source", temp);
    return;
  }
  if (fault === "final-plus-temp" || fault === "final-plus-incomplete-temp") {
    writeStrictCurrentEntryFixtureRecordV1(original.store, record.locator, record.bytes);
    writeTemp(0, fault === "final-plus-temp" ? record.bytes : incomplete);
    return;
  }
  if (fault === "unequal-final") {
    writeStrictCurrentEntryFixtureRecordV1(original.store, record.locator, Buffer.from("{}\n", "utf8"));
    return;
  }
  if (fault === "wrong-final-mode") {
    writeStrictCurrentEntryFixtureRecordV1(original.store, record.locator, record.bytes);
    chmodSync(target, 0o644);
    return;
  }
  if (fault === "wrong-final-link-count") {
    writeStrictCurrentEntryFixtureRecordV1(original.store, record.locator, record.bytes);
    linkSync(target, `${target}.alias`);
    return;
  }
  writeStrictCurrentEntryFixtureRecordV1(original.store, relative(path.join(path.dirname(target), ".symlink-final-source")), record.bytes);
  symlinkSync(".symlink-final-source", target);
}

function configureExactPoisonRecoveryLeafHarnessV1(
  root: string,
  fault: ExactPoisonRecoveryLeafFaultFixtureV1 | null = null,
): Readonly<{
  original: ExactOriginalPoisonStoreFixtureV1;
  admitted: Readonly<{ chain: ExactPoisonStrictChainFixtureV1; value: Readonly<Record<string, unknown>> }>;
  observations: Readonly<Record<string, readonly unknown[]>>;
}> {
  installExactCurrentSuccessorGitFixtureV1(root);
  const original = seedExactOriginalPoisonStoreV1(root);
  const admitted = buildExactPoisonPublisherAdmissionFixtureV1(root, original);
  const observations = buildExactPoisonPublisherRawObservationsV1(admitted);
  instrumentExactPoisonRecoveryLeafFixtureV1(root, fault);
  instrumentExactPoisonPublisherCoreFixtureV1(root, original, null);
  return Object.freeze({ original, admitted, observations });
}

type ExactPoisonDurabilityKindFixtureV1 = "seal" | "commit";
type ExactPoisonDurabilityBoundaryFixtureV1 = "pre-fsync" | "post-fsync" | "post-reopen";
type ExactPoisonDurabilityFaultFixtureV1 = Readonly<{
  kind: ExactPoisonDurabilityKindFixtureV1;
  boundary: ExactPoisonDurabilityBoundaryFixtureV1;
  occurrence: number;
  action: "throw" | "latch";
  readyPath?: string;
  releasePath?: string;
}>;

type ExactPoisonPinnedContextBoundaryFixtureV1 =
  | "builder-operation-pre-read"
  | "builder-operation-post-read"
  | "stable-member-post-read";
type ExactPoisonPinnedContextFaultFixtureV1 = Readonly<{
  boundary: ExactPoisonPinnedContextBoundaryFixtureV1;
  occurrence: number;
  readyPath: string;
  releasePath: string;
}>;

function instrumentExactPoisonDurabilityFixtureV1(root: string): void {
  const modulePath = path.join(root, "src/internal-production/baseline-post-handoff-receipt-v1.ts");
  let source = readFileSync(modulePath, "utf8");
  const sealBuilder = "async function openExactPoisonRecoveryPinnedSealChainV1(): Promise<ExactPoisonRecoveryPinnedSealChainV1> {";
  const commitBuilder = "async function openExactPoisonRecoveryPinnedCommitChainV1(): Promise<ExactPoisonRecoveryPinnedCommitChainV1> {";
  const sealHelper = "async function durablyAuthenticateSuccessorActivationSealV1(";
  const commitHelper = "async function durablyAuthenticateSuccessorActivationCommitV1(";
  const faultMarker = "function exactPoisonRecoveryDurabilityFaultV1(";
  for (const [marker, label] of [
    [sealBuilder, "zero-input pinned seal-chain builder"],
    [commitBuilder, "zero-input pinned commit-chain builder"],
    [sealHelper, "publisher-only seal durability helper"],
    [commitHelper, "generic commit durability helper"],
    [faultMarker, "private inert durability fault boundary"],
  ] as const) assert.equal(source.split(marker).length - 1, 1, `production must retain one ${label}`);

  source = source.replace(sealBuilder, `export ${sealBuilder}`);
  source = source.replace(commitBuilder, `export ${commitBuilder}`);
  source = source.replace(sealHelper, `export ${sealHelper}`);
  source = source.replace(commitHelper, `export ${commitHelper}`);

  const faultStart = source.indexOf(faultMarker);
  const faultEnd = source.indexOf("\n}\n", faultStart);
  assert.ok(faultStart >= 0 && faultEnd > faultStart, "the private durability fault boundary must have one exact copied-module body");
  const faultSignatureEnd = source.indexOf("): void {", faultStart);
  assert.ok(faultSignatureEnd > faultStart && faultSignatureEnd < faultEnd, "the private durability fault boundary must return void");
  const injectedFaultBody = `): void {
  const probe = Reflect.get(globalThis, "__p5aExactPoisonDurabilityProbeV1") as undefined | {
    events: string[];
    matches: number;
    fault: null | Readonly<{kind:string;boundary:string;occurrence:number;action:"throw"|"latch";readyPath?:string;releasePath?:string}>;
  };
  if (probe === undefined) return;
  probe.events.push(kind + ":" + boundary);
  const expected = probe.fault;
  if (expected === null || expected.kind !== kind || expected.boundary !== boundary) return;
  probe.matches += 1;
  if (probe.matches !== expected.occurrence) return;
  if (expected.action === "throw") throw new Error("P5A_EXACT_POISON_DURABILITY_FAULT:" + kind + ":" + boundary);
  if (!expected.readyPath || !expected.releasePath) throw new Error("P5A_EXACT_POISON_DURABILITY_LATCH_PATH_MISSING");
  writeFileSync(expected.readyPath, "ready\\n", { flag: "wx", mode: 0o600 });
  const wait = new Int32Array(new SharedArrayBuffer(4));
  for (;;) {
    try { lstatSync(expected.releasePath); return; }
    catch (error) { if (!isEnoent(error)) throw error; Atomics.wait(wait, 0, 0, 5); }
  }
}`;
  source = source.slice(0, faultSignatureEnd) + injectedFaultBody + source.slice(faultEnd + 2);

  const operationSnapshotAnchor = `  const operation = requireExactPoisonRecoverySnapshotV1(
    fixedLegacyCurrentEntryOperationPathV1(),
    "fixed legacy exact-poison pinned operation",
  );
  const parsed = await readExactPoisonRecoveryChainV1(operation, includeCommit);`;
  assert.equal(source.split(operationSnapshotAnchor).length - 1, 1, "the copied builder has one initial fixed-operation snapshot boundary");
  source = source.replace(operationSnapshotAnchor, `  p5aExactPoisonPinnedContextFaultFixtureV1("builder-operation-pre-read", fixedLegacyCurrentEntryOperationPathV1());
  const operation = requireExactPoisonRecoverySnapshotV1(
    fixedLegacyCurrentEntryOperationPathV1(),
    "fixed legacy exact-poison pinned operation",
  );
  p5aExactPoisonPinnedContextFaultFixtureV1("builder-operation-post-read", fixedLegacyCurrentEntryOperationPathV1());
  const parsed = await readExactPoisonRecoveryChainV1(operation, includeCommit);`);

  const stableFunctionMarker = "function assertExactPoisonRecoveryPinnedMemberStableV1(";
  const stableStart = source.indexOf(stableFunctionMarker);
  const stableEnd = source.indexOf("\n}\n", stableStart);
  assert.ok(stableStart >= 0 && stableEnd > stableStart, "the copied module retains one pinned-member stable fence");
  const stableRegion = source.slice(stableStart, stableEnd + 2);
  const stableReadAnchor = `  const bytes = readTask12ReceiptDescriptorBytesV1(pinned.descriptor, now.size);
  const after = fstatSync(pinned.descriptor, { bigint: true });`;
  const legacyStableReadAnchor = "    || !readTask12ReceiptDescriptorBytesV1(pinned.descriptor, now.size).equals(pinned.bytes)";
  const stableReadCount = stableRegion.split(stableReadAnchor).length - 1;
  const legacyStableReadCount = stableRegion.split(legacyStableReadAnchor).length - 1;
  assert.equal(stableReadCount + legacyStableReadCount, 1, "the copied stable fence has one current or legacy descriptor-read boundary");
  const instrumentedStableRegion = stableReadCount === 1
    ? stableRegion.replace(stableReadAnchor, `  const bytes = readTask12ReceiptDescriptorBytesV1(pinned.descriptor, now.size);
  p5aExactPoisonPinnedContextFaultFixtureV1("stable-member-post-read", target);
  const after = fstatSync(pinned.descriptor, { bigint: true });`)
    : stableRegion.replace(legacyStableReadAnchor, `    || !(() => {
      const bytes = readTask12ReceiptDescriptorBytesV1(pinned.descriptor, now.size);
      p5aExactPoisonPinnedContextFaultFixtureV1("stable-member-post-read", target);
      return bytes;
    })().equals(pinned.bytes)`);
  source = source.slice(0, stableStart) + instrumentedStableRegion + source.slice(stableEnd + 2);

  const coreMarker = "async function resumeExactPoisonQuarantinePublisherCoreV1(): Promise<void> {";
  const coreMarkerStart = source.indexOf(coreMarker);
  assert.ok(coreMarkerStart >= 0, "the durability fixture requires the private publisher core");
  const coreStart = source.lastIndexOf("\n", coreMarkerStart) + 1;
  const wrapper = `function p5aExactPoisonPinnedContextFaultFixtureV1(boundary: "builder-operation-pre-read" | "builder-operation-post-read" | "stable-member-post-read", target: string): void {
  const probe = Reflect.get(globalThis, "__p5aExactPoisonPinnedContextProbeV1") as undefined | {
    events: ReadonlyArray<{boundary:string;target:string}>;
    matches: number;
    fault: null | Readonly<{boundary:string;occurrence:number;readyPath:string;releasePath:string}>;
  };
  if (probe === undefined) return;
  (probe.events as Array<{boundary:string;target:string}>).push({ boundary, target });
  const expected = probe.fault;
  if (expected === null || expected.boundary !== boundary) return;
  probe.matches += 1;
  if (probe.matches !== expected.occurrence) return;
  writeFileSync(expected.readyPath, "ready\\n", { flag: "wx", mode: 0o600 });
  const wait = new Int32Array(new SharedArrayBuffer(4));
  for (;;) {
    try { lstatSync(expected.releasePath); return; }
    catch (error) { if (!isEnoent(error)) throw error; Atomics.wait(wait, 0, 0, 5); }
  }
}

export async function p5aRunExactPoisonDurabilityFixtureV1(kind: "seal" | "commit", writerMode: "real" | "clone" = "real"): Promise<Readonly<Record<string, unknown>>> {
  const beforeDescriptors = readdirSync("/dev/fd").filter((name) => /^[0-9]+$/.test(name)).length;
  let writer: ExactPoisonRecoveryWriterV1 | null = null;
  let context: ExactPoisonRecoveryPinnedSealChainV1 | ExactPoisonRecoveryPinnedCommitChainV1 | null = null;
  try {
    if (kind === "seal" && writerMode === "real") writer = acquireExactPoisonRecoveryWriterV1();
    context = kind === "seal"
      ? await openExactPoisonRecoveryPinnedSealChainV1()
      : await openExactPoisonRecoveryPinnedCommitChainV1();
    if (kind === "seal") {
      if (writerMode === "clone") writer = Object.freeze({ assertStable: () => undefined, close: () => undefined }) as ExactPoisonRecoveryWriterV1;
      await durablyAuthenticateSuccessorActivationSealV1(context as ExactPoisonRecoveryPinnedSealChainV1, writer!);
    } else {
      await durablyAuthenticateSuccessorActivationCommitV1(context as ExactPoisonRecoveryPinnedCommitChainV1);
    }
    context.assertStable();
    return recursivelyFreeze({
      frozen: Object.isFrozen(context),
      successorRoot: context.successorRoot,
      successorOperationPair: context.successorOperationPair,
      sealParentTarget: context.sealParent.target,
      commitParentTarget: "commitParent" in context ? context.commitParent.target : null,
      contextKeys: Reflect.ownKeys(context).filter((key): key is string => typeof key === "string").sort(compareBytes),
      beforeDescriptors,
    });
  } finally {
    try { context?.close(); }
    finally { if (writer !== null && writerMode === "real") writer.close(); }
  }
}

`;
  source = source.slice(0, coreStart) + wrapper + source.slice(coreStart);
  writeFileSync(modulePath, source);
}

function configureExactPoisonDurabilityHarnessV1(
  root: string,
  kind: ExactPoisonDurabilityKindFixtureV1,
): Readonly<{
  original: ExactOriginalPoisonStoreFixtureV1;
  admitted: Readonly<{ chain: ExactPoisonStrictChainFixtureV1; value: Readonly<Record<string, unknown>> }>;
  seeded: ReturnType<typeof seedExactPoisonStrictChainFixtureV1>;
}> {
  installExactCurrentSuccessorGitFixtureV1(root);
  const original = seedExactOriginalPoisonStoreV1(root);
  const admitted = buildExactPoisonPublisherAdmissionFixtureV1(root, original);
  rewriteExactPoisonPhysicalInventoryFixtureV1(root, original);
  const seeded = seedExactPoisonStrictChainFixtureV1(root, admitted.chain, kind === "seal" ? "S" : "C");
  instrumentExactPoisonDurabilityFixtureV1(root);
  return Object.freeze({ original, admitted, seeded });
}

function runExactPoisonDurabilityFixtureV1(
  root: string,
  kind: ExactPoisonDurabilityKindFixtureV1,
  fault: ExactPoisonDurabilityFaultFixtureV1 | null = null,
  writerMode: "real" | "clone" = "real",
  contextFault: ExactPoisonPinnedContextFaultFixtureV1 | null = null,
): Promise<Readonly<{ status: number | null; stdout: string; stderr: string }>> {
  return runFixtureExpressionAsync(root, `(async()=>{const fs=await import("node:fs");const before=fs.readdirSync("/dev/fd").filter((name)=>/^[0-9]+$/.test(name)).length;const probe={events:[],matches:0,fault:${JSON.stringify(fault)}};const contextProbe={events:[],matches:0,fault:${JSON.stringify(contextFault)}};Reflect.set(globalThis,"__p5aExactPoisonDurabilityProbeV1",probe);Reflect.set(globalThis,"__p5aExactPoisonPinnedContextProbeV1",contextProbe);let outcome="returned",message=null,value=null;try{value=await m.p5aRunExactPoisonDurabilityFixtureV1(${JSON.stringify(kind)},${JSON.stringify(writerMode)})}catch(error){outcome="threw";message=String(error)}const after=fs.readdirSync("/dev/fd").filter((name)=>/^[0-9]+$/.test(name)).length;process.stdout.write(JSON.stringify({outcome,message,value,events:probe.events,matches:probe.matches,contextEvents:contextProbe.events,contextMatches:contextProbe.matches,descriptorDelta:after-before}))})()`);
}

function runExactPoisonPublisherCoreWithDurabilityFixtureV1(
  root: string,
  observations: Readonly<Record<string, readonly unknown[]>>,
): ReturnType<typeof spawnSync> {
  const transported = JSON.stringify(fixtureTransportValueV1(observations));
  const transportPath = path.join(path.dirname(root), ".p5a-exact-poison-admission.json");
  fixtureFile(path.dirname(root), ".p5a-exact-poison-admission.json", `${transported}\n`, 0o600);
  return runFixtureExpression(root, `(async()=>{const {readFileSync}=await import("node:fs");const revive=(value)=>{if(Array.isArray(value))return value.map(revive);if(value&&typeof value==="object"){if(Object.keys(value).length===1&&typeof value.__p4ExactBufferBase64V1==="string")return Buffer.from(value.__p4ExactBufferBase64V1,"base64");return Object.fromEntries(Object.entries(value).map(([key,entry])=>[key,revive(entry)]))}return value};const values=revive(JSON.parse(readFileSync(${JSON.stringify(transportPath)},"utf8")));const cursors={};const next=(kind)=>{const sequence=values[kind];if(!Array.isArray(sequence)||sequence.length===0)throw new Error("P5A_EXACT_POISON_RAW_SEQUENCE_MISSING:"+kind);const cursor=cursors[kind]??0;cursors[kind]=cursor+1;return sequence[cursor%sequence.length]};const admission={admissionCalls:0,cursors,next,nextPhysical:(..._args)=>next("physical"),nextPhase:(..._args)=>next("phase"),observeSyntheticGit:(..._args)=>next("syntheticGit")};const durability={events:[],matches:0,fault:null};Reflect.set(globalThis,"__p4ExactPoisonPublisherAdmissionV1",admission);Reflect.set(globalThis,"__p5aExactPoisonDurabilityProbeV1",durability);let outcome="returned",message=null;try{await m.resumeExactPoisonQuarantinePublisherCoreV1()}catch(error){outcome="threw";message=String(error)}process.stdout.write(JSON.stringify({outcome,message,events:durability.events,admissionCalls:admission.admissionCalls}))})()`);
}

