type P5cSActiveRecoveryAdoptionProbeV1=Readonly<{fence:Readonly<Record<string,unknown>>;pairClose:Readonly<Record<string,unknown>>;release:Readonly<Record<string,unknown>>}> & {reobserveCalls:number;closeTargetCalls:number;releaseCalls:number;releaseFaults?:number;events:string[]};
const p5cSActiveRecoveryAdoptionProbeV1=():P5cSActiveRecoveryAdoptionProbeV1=>Reflect.get(globalThis,"__p5cSActiveRecoveryAdoptionProbeV1") as P5cSActiveRecoveryAdoptionProbeV1;
