function phase5cSCorruptProgressEffectResultFixtureV1(
  value: Readonly<Record<string, unknown>>,
  corruption: "missing" | "crossed",
): Readonly<Record<string, unknown>> {
  const output = structuredClone(value) as Record<string, unknown>;
  const payloadKey = Object.keys(output).find((key) => key !== "effect")!;
  if (corruption === "missing") delete output[payloadKey];
  else {
    const visit = (candidate: unknown): boolean => {
      if (typeof candidate !== "object" || candidate === null || Array.isArray(candidate)) return false;
      const record = candidate as Record<string, unknown>;
      const hashKey = Object.keys(record).find((key) => key.endsWith("Hash") && typeof record[key] === "string");
      if (hashKey !== undefined) { record[hashKey] = "f".repeat(64); return true; }
      for (const nested of Object.values(record)) if (visit(nested)) return true;
      return false;
    };
    if (!visit(output[payloadKey])) output[payloadKey] = Object.freeze({ ...(output[payloadKey] as Readonly<Record<string, unknown>>), state: "crossed" });
  }
  return Object.freeze(output);
}

