    const active = endpoints[Number(external.activeEndpointOrdinal)]!;
    const database = active.database as Readonly<Record<string, unknown>>;
    assert.equal(database.state, "current", `${descriptor.row}: completed DB33 evidence is one exact atomic current projection`);
    const migration33ReadOnly = JSON.parse(Buffer.from(String(database.expectedProjectionBase64), "base64").toString("utf8")) as Readonly<Record<string, unknown>>;
    assert.equal(migration33ReadOnly.state, "current", `${descriptor.row}: completed DB33 bytes decode to current`);
    assertBound((migration33ReadOnly.journal as Readonly<Record<string, unknown>>).checksum, external, "migration33 journal checksum");
