  if (previous !== null) assert.equal(previous.equals(current), false, `${descriptor.row}: authenticated previous and current Task12 pairs are distinct`);
  return Object.freeze({ previousPairBytesBase64: previous?.toString("base64") ?? null, currentPairBytesBase64: current.toString("base64"), nextPairBytesBase64: next?.toString("base64") ?? null });
