function phase5cSRowTailPhysicalCurrentFixtureV1(
  descriptor: typeof PHASE5C_S_NONBLOCKED_ROWS_V1[number],
): Readonly<Record<string, unknown>> {
  const status = phase5cSCanonicalProgressStatusFixtureV1(descriptor.row);
  const selectedCurrentEntryOperation = Object.freeze({ operationRef: status.operationRef, operationHash: status.operationHash });
  const rowIndex = PHASE5C_S_NONBLOCKED_ROWS_V1.indexOf(descriptor);
  if (rowIndex < 12) return Object.freeze({ state: "pre-recovery", row: descriptor.row, selectedCurrentEntryOperation, recoverySourceBootstrap: null, recoverySourceOperation: null, ownerAdmissionFence: null, sourceRunReservation: null, runReservation: null, ownerAdmissionHead: phase5cSOwnerAdmissionGenesisHeadFixtureV1() });
  const recoveryArrow = (ordinal: number): typeof PHASE5C_S_EXTERNAL_RAW_ARROWS_V1[number] => PHASE5C_S_EXTERNAL_RAW_ARROWS_V1.find((candidate) => candidate.family === "recovery-source" && candidate.ordinal === ordinal)!;
  const chain = phase5cSExternalRawCausalChainFixtureV1(recoveryArrow(rowIndex === 12 ? 0 : rowIndex <= 14 ? 1 : 2));
  const recoverySourceBootstrap = rowIndex === 12 ? chain.prior! : chain.next;
  const materials = chain.materials;
  const recoverySourceOperation = materials["recovery-operation"] as Readonly<Record<string, unknown>>;
  const databaseFenceReservations = materials["database-fence-reservations"] as Readonly<Record<string, Readonly<Record<string, unknown>>>>;
  assert.deepEqual(
    { operationRef: recoverySourceBootstrap.operationRef, operationHash: recoverySourceBootstrap.operationHash },
    recoverySourceBootstrap.state === "absent" ? { operationRef: null, operationHash: null } : { operationRef: recoverySourceOperation.operationRef, operationHash: recoverySourceOperation.operationHash },
    `${descriptor.row}: recovery current and its canonical recovery operation are exact`,
  );
  if (recoverySourceBootstrap.state !== "absent") assert.notDeepEqual(
    { operationRef: recoverySourceOperation.operationRef, operationHash: recoverySourceOperation.operationHash },
    selectedCurrentEntryOperation,
    `${descriptor.row}: the recovery bootstrap operation is intentionally nonalias to the selected current-entry operation`,
  );
  const prepared = recoverySourceBootstrap.state === "prepared";
  const terminal = recoverySourceBootstrap.state === "terminal";
  return Object.freeze({
    state: recoverySourceBootstrap.state,
    row: descriptor.row,
    selectedCurrentEntryOperation,
    recoverySourceBootstrap,
    recoverySourceOperation: recoverySourceBootstrap.state === "absent" ? null : recoverySourceOperation,
    ownerAdmissionFence: prepared ? databaseFenceReservations.fence : null,
    sourceRunReservation: prepared ? databaseFenceReservations.sourceReservation : null,
    runReservation: prepared ? databaseFenceReservations.runReservation : null,
    ownerAdmissionHead: prepared
      ? databaseFenceReservations.ownerAdmissionHead
      : terminal
        ? databaseFenceReservations.releasedOwnerAdmissionHead
        : phase5cSOwnerAdmissionGenesisHeadFixtureV1(),
    ownerAdmissionHistory: prepared ? Object.freeze({
      fence: databaseFenceReservations.fence,
      sourceReservation: databaseFenceReservations.sourceReservation,
      runReservation: databaseFenceReservations.runReservation,
      ownerAdmissionHead: databaseFenceReservations.ownerAdmissionHead,
    }) : terminal ? databaseFenceReservations : null,
  });
}

