function phase5cSExternalRawStatusFixtureV1(
  arrow: typeof PHASE5C_S_EXTERNAL_RAW_ARROWS_V1[number],
  side: "prior" | "next",
): Readonly<Record<string, unknown>> {
  return phase5cSExternalRawCausalChainFixtureV1(arrow)[side];
}

function phase5cSSeedPreSchemaAtRootPhysicalFixtureV1(
  root: string,
  terminalOrdinal: -1 | 0 | 1 | 2 | 3 | 4 | 5 | 6,
  blocked = false,
): Readonly<{
  operation: Readonly<{ operationRef: string; operationHash: string }>;
  current: Readonly<Record<string, unknown>>;
  successorRoot: string;
  operationDirectory: string;
  currentStatusTarget: string;
  currentStatusContentTarget: string;
  authorizationContentTarget: string;
  sealedAdmissionLocatorTarget: string;
}> {
  const operation = phase5cSAuthenticPreSchemaCurrentEntryOperationFixtureV1();
  const successorRoot = path.join(path.dirname(root), "data/internal-production-baseline/current-entry-poison-successor-v1");
  const operationDirectory = path.join(root, "data/internal-production-baseline/pre-schema-spawner-rebind-v1/operations/sha256", String(operation.operationHash));
  mkdirSync(successorRoot, { recursive: true, mode: 0o700 });
  const authorityV3Migration31Audit = JSON.parse(exactCurrentAuthorityV31FixtureBytesV1().toString("utf8")) as Readonly<Record<string, unknown>>;
  const authorityV3Migration31AuditHash = String(authorityV3Migration31Audit.authorityV3Migration31AuditHash);
  const authorityV3Migration31AuditTarget = path.join(path.dirname(root), "data/internal-production-baseline/current-entry-v1/records/authority-v3-migration31-audits/sha256", authorityV3Migration31AuditHash.slice(0, 2), `${authorityV3Migration31AuditHash}.json`);
  phase5cEnsurePublicationParentV1(authorityV3Migration31AuditTarget);
  writeFileSync(authorityV3Migration31AuditTarget, canonicalFixtureRecordV1(authorityV3Migration31Audit), { mode: 0o600 });
  if (terminalOrdinal === -1) {
    const firstArrow = PHASE5C_S_EXTERNAL_RAW_ARROWS_V1.find((candidate) => candidate.family === "pre-schema" && candidate.ordinal === 0)!;
    const current = phase5cSExternalRawCausalChainFixtureV1(firstArrow, "B").prior!;
    mkdirSync(path.dirname(operationDirectory), { recursive: true, mode: 0o700 });
    return Object.freeze({ operation, current, successorRoot, operationDirectory, currentStatusTarget: path.join(operationDirectory, PHASE5C_S_PRE_SCHEMA_PHYSICAL_STATUS_BASENAMES_V1[0]!), currentStatusContentTarget: path.join(root, ".absent-status"), authorizationContentTarget: path.join(root, ".absent-authorization"), sealedAdmissionLocatorTarget: path.join(operationDirectory, "07-sealed-admission.pair.json") });
  }
  const arrows = Array.from({ length: terminalOrdinal + 1 }, (_, ordinal) => {
    const arrow = PHASE5C_S_EXTERNAL_RAW_ARROWS_V1.find((candidate) => candidate.family === "pre-schema" && candidate.ordinal === ordinal && candidate.next !== "blocked");
    assert.ok(arrow, `pre-schema physical ordinal ${ordinal} exists`);
    return arrow;
  });
  const chains = arrows.map((arrow) => phase5cSExternalRawCausalChainFixtureV1(arrow, "B"));
  const materials = chains[0]!.materials;
  let current = chains.at(-1)!.next;
  assert.deepEqual(current.currentEntryOperation, Object.freeze({ operationRef: operation.operationRef, operationHash: operation.operationHash }), "physical pre-schema status binds the authentic self-hashed operation pair");
  const contentRoot = path.join(root, "data/internal-production-baseline/pre-schema-spawner-rebind-v1/records");
  const writeCanonical = (target: string, value: Readonly<Record<string, unknown>>): void => {
    phase5cEnsurePublicationParentV1(target);
    writeFileSync(target, canonicalFixtureRecordV1(value), { mode: 0o600 });
  };
  const pair = (value: Readonly<Record<string, unknown>>, refKey: string, hashKey: string): Readonly<Record<string, unknown>> => Object.freeze({ [refKey]: value[refKey], [hashKey]: value[hashKey] });
  const record = (kind: string, value: Readonly<Record<string, unknown>>, hashKey: string): void => {
    const hash = String(value[hashKey]);
    writeCanonical(path.join(contentRoot, kind, "sha256", hash.slice(0, 2), `${hash}.json`), value);
  };
  const locatorRows = Object.freeze([
    Object.freeze({ ordinal: 0, name: "00-pre-dispatch-legacy-zero.pair.json", material: "pre-dispatch-legacy-zero-content", refKey: "observationRef", hashKey: "observationHash" }),
    Object.freeze({ ordinal: 0, name: "01-authorization.pair.json", material: "authorization", refKey: "authorizationRef", hashKey: "authorizationHash" }),
    Object.freeze({ ordinal: 1, name: "02-startup-token.pair.json", material: "startup-token", refKey: "startupTokenRef", hashKey: "startupTokenHash" }),
    Object.freeze({ ordinal: 2, name: "03-restart-authority.pair.json", material: "restart-authority", refKey: "restartAuthorityRef", hashKey: "restartAuthorityHash" }),
    Object.freeze({ ordinal: 3, name: "04-predecessor-termination.pair.json", material: "predecessor-termination", refKey: "predecessorTerminationObservationRef", hashKey: "predecessorTerminationObservationHash" }),
    Object.freeze({ ordinal: 4, name: "05-replacement-process.pair.json", material: "replacement-process", refKey: "replacementProcessObservationRef", hashKey: "replacementProcessObservationHash" }),
    Object.freeze({ ordinal: 5, name: "06-post-termination-legacy-zero.pair.json", material: "post-termination-legacy-zero-content", refKey: "observationRef", hashKey: "observationHash" }),
    Object.freeze({ ordinal: 5, name: "07-sealed-admission.pair.json", material: "sealed-admission", refKey: "sealedAdmissionRef", hashKey: "sealedAdmissionHash" }),
    Object.freeze({ ordinal: 6, name: "08-admission-ready.pair.json", material: "admission-ready", refKey: "admissionReadyRef", hashKey: "admissionReadyHash" }),
  ] as const);
  for (const row of locatorRows) {
    if (row.ordinal > terminalOrdinal) continue;
    const value = materials[row.material]!;
    writeCanonical(path.join(operationDirectory, row.name), pair(value, row.refKey, row.hashKey));
  }
  for (const [ordinal, chain] of chains.entries()) {
    const status = chain.next;
    writeCanonical(path.join(operationDirectory, PHASE5C_S_PRE_SCHEMA_PHYSICAL_STATUS_BASENAMES_V1[ordinal]!), pair(status, "statusRef", "statusHash"));
    record("status", status, "statusHash");
  }
  if (blocked) {
    assert.equal(terminalOrdinal, 2, "blocked physical history branches only from the restart-authority prefix");
    const blockedArrow = PHASE5C_S_EXTERNAL_RAW_ARROWS_V1.find((candidate) => candidate.family === "pre-schema" && candidate.next === "blocked")!;
    const blockedStatus = phase5cSExternalRawCausalChainFixtureV1(blockedArrow, "B").next;
    const blockedTarget = path.join(operationDirectory, "status-blocked-helper-dispatch-settlement-unknown.pair.json");
    writeCanonical(blockedTarget, pair(blockedStatus, "statusRef", "statusHash"));
    record("status", blockedStatus, "statusHash");
    current = blockedStatus;
  }
  const contentRows = Object.freeze([
    Object.freeze({ ordinal: 0, material: "authorization", kind: "authorization", hashKey: "authorizationHash" }),
    Object.freeze({ ordinal: 1, material: "predecessor-process-identity", kind: "process-identity", hashKey: null }),
    Object.freeze({ ordinal: 1, material: "startup-token", kind: "startup-token", hashKey: "startupTokenHash" }),
    Object.freeze({ ordinal: 2, material: "restart-authority", kind: "restart-authority", hashKey: "restartAuthorityHash" }),
    Object.freeze({ ordinal: 3, material: "predecessor-termination", kind: "predecessor-termination", hashKey: "predecessorTerminationObservationHash" }),
    Object.freeze({ ordinal: 4, material: "replacement-process-identity", kind: "process-identity", hashKey: null }),
    Object.freeze({ ordinal: 4, material: "replacement-process", kind: "replacement-process", hashKey: "replacementProcessObservationHash" }),
    Object.freeze({ ordinal: 5, material: "sealed-admission", kind: "sealed-admission", hashKey: "sealedAdmissionHash" }),
    Object.freeze({ ordinal: 6, material: "admission-ready", kind: "admission-ready", hashKey: "admissionReadyHash" }),
  ] as const);
  for (const row of contentRows) {
    if (row.ordinal > terminalOrdinal) continue;
    const value = materials[row.material]!;
    const hash = row.hashKey === null ? canonicalHash(value) : String(value[row.hashKey]);
    writeCanonical(path.join(contentRoot, row.kind, "sha256", hash.slice(0, 2), `${hash}.json`), value);
  }
  for (const material of ["pre-dispatch-legacy-zero-content", ...(terminalOrdinal >= 5 ? ["post-termination-legacy-zero-content"] : [])]) {
    const value = materials[material]!;
    const hash = String(value.observationHash);
    writeCanonical(path.join(path.dirname(root), "data/internal-production-baseline/legacy-pre-manifest-zero-owner-observation-v1/records/sha256", hash.slice(0, 2), `${hash}.json`), value);
  }
  const currentStatusTarget = blocked
    ? path.join(operationDirectory, "status-blocked-helper-dispatch-settlement-unknown.pair.json")
    : path.join(operationDirectory, PHASE5C_S_PRE_SCHEMA_PHYSICAL_STATUS_BASENAMES_V1[terminalOrdinal]!);
  const currentStatusHash = String(current.statusHash);
  const currentStatusContentTarget = path.join(contentRoot, "status", "sha256", currentStatusHash.slice(0, 2), `${currentStatusHash}.json`);
  assert.deepEqual(readdirSync(operationDirectory).sort(), [
    ...locatorRows.filter((row) => row.ordinal <= terminalOrdinal).map((row) => row.name),
    ...PHASE5C_S_PRE_SCHEMA_PHYSICAL_STATUS_BASENAMES_V1.slice(0, terminalOrdinal + 1),
    ...(blocked ? ["status-blocked-helper-dispatch-settlement-unknown.pair.json"] : []),
  ].sort(), "pre-schema physical fixture exposes only its exact contiguous operation history");
  const authorizationHash = String(materials.authorization!.authorizationHash);
  const authorizationContentTarget = path.join(contentRoot, "authorization", "sha256", authorizationHash.slice(0, 2), `${authorizationHash}.json`);
  const sealedAdmissionLocatorTarget = path.join(operationDirectory, "07-sealed-admission.pair.json");
  return Object.freeze({ operation, current, successorRoot, operationDirectory, currentStatusTarget, currentStatusContentTarget, authorizationContentTarget, sealedAdmissionLocatorTarget });
}

