  controllerConstructionInput: Readonly<{ storeRoot: string; operation: InternalProductionCurrentEntryOperationV1; faultStage: "root-reader-open" | "operation-directory-guard-open" | "operation-directory-guard-stable"; rootCloseFault: boolean; operationCloseFault: boolean }> | null = null,
