  it("P5c-S re-fences the live selected root and operation directory at every internal adjacent-advance await/effect boundary", async () => {
    const boundaries = Object.freeze([
      Object.freeze({ boundary: "after-content-canonical", publicationCalls: 0, casCalls: 0, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "after-pair-canonical", publicationCalls: 0, casCalls: 0, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "pre-content-publish", publicationCalls: 0, casCalls: 0, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "pre-current-status-cas", publicationCalls: 1, casCalls: 0, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "after-cas-expected-canonical", publicationCalls: 1, casCalls: 1, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "after-cas-successor-canonical", publicationCalls: 1, casCalls: 1, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "pre-physical-current-status-cas", publicationCalls: 1, casCalls: 1, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "before-normalizer-first-mutation", publicationCalls: 1, casCalls: 1, physicalCasCalls: 0, reopenCalls: 0 }),
      Object.freeze({ boundary: "post-current-status-cas", publicationCalls: 1, casCalls: 1, physicalCasCalls: 1, reopenCalls: 0 }),
      Object.freeze({ boundary: "post-status-reopen", publicationCalls: 1, casCalls: 1, physicalCasCalls: 1, reopenCalls: 1 }),
    ] as const);
    for (const mutation of ["selected-root-aba", "operation-directory-aba"] as const) {
      for (const expected of boundaries) {
        const root = createFixture();
        try {
          const harness = configurePhase5cZeroProgressFixtureV1(root, true);
          instrumentPhase5cProgressResumeFixtureV1(root, true);
          const seeded = await runPhase5cZeroProgressFixtureV1(root, harness.observations, Object.freeze({ kind: "none" }), "prepare");
          assert.equal((JSON.parse(seeded.stdout) as Readonly<Record<string, unknown>>).outcome, "returned", seeded.stderr);
          const storeRoot = realpathSync(path.join(harness.original.store, harness.admitted.chain.successorStoreRelativeRoot));
          const operation = harness.admitted.chain.records.successorOperation.value as InternalProductionCurrentEntryOperationV1;
          const retained = phase5cSSeedRetainedReaderFixturesV1(root, operation).preSchema[0]!;
          const effectResult = Object.freeze({ effect: "resume-pre-schema", preSchemaSpawnerRebindStatus: retained.pair, preSchemaSpawnerRebindStatusBody: retained.body });
          const before = filesystemTreeSnapshot(harness.original.store);
          const result = await runFixtureExpressionAsync(root, `(async()=>{const fs=await import("node:fs");const count=()=>fs.readdirSync("/dev/fd").filter((name)=>/^[0-9]+$/.test(name)).length;const before=count();try{const value=await m.p5cSAdvanceCandidatePhysicalAbaFixtureV1(${JSON.stringify({ storeRoot, operation, mutation, boundary: expected.boundary, effectResult })});process.stdout.write(JSON.stringify({outcome:"returned",value,descriptorDelta:count()-before}))}catch(error){process.stdout.write(JSON.stringify({outcome:"threw",message:String(error),descriptorDelta:count()-before}))}})()`);
          assert.equal(result.status, 0, result.stderr);
          const observed = JSON.parse(result.stdout) as Readonly<Record<string, unknown>>;
          assert.equal(observed.outcome, "returned", `${mutation}:${expected.boundary}: copied real candidate-advance seam is executable: ${JSON.stringify(observed)}`);
          const value = observed.value as Readonly<Record<string, unknown>>;
          assert.equal(value.mutationApplied, true, `${mutation}:${expected.boundary}: the requested physical generation swap occurs inside the real adjacent advance`);
          assert.equal((value.boundaryHits as readonly string[]).includes(expected.boundary), true, `${mutation}:${expected.boundary}: the exact internal boundary is reached once`);
          assert.deepEqual({ ownerCloses: value.ownerCloses, controllerReleases: value.controllerReleases, descriptorDelta: observed.descriptorDelta }, { ownerCloses: 1, controllerReleases: 1, descriptorDelta: 0 },
            `${mutation}:${expected.boundary}: owner/controller cleanup is exact after the internal ABA`);
          assert.deepEqual(filesystemTreeSnapshot(harness.original.store), before, `${mutation}:${expected.boundary}: the selected store and candidate artifacts are restored exactly`);
          assert.equal(value.outcome, "threw", `${mutation}:${expected.boundary}: the first root-only fence after the internal boundary rejects the real generation replacement: ${JSON.stringify(value)}`);
          assert.match(String(value.message), /directory chain changed|identity changed|member identity|root|operation directory|authority/i, JSON.stringify(value));
          assert.deepEqual(
            { publicationCalls: value.publicationCalls, casCalls: value.casCalls, physicalCasCalls: value.physicalCasCalls, reopenCalls: value.reopenCalls },
            { publicationCalls: expected.publicationCalls, casCalls: expected.casCalls, physicalCasCalls: expected.physicalCasCalls, reopenCalls: expected.reopenCalls },
            `${mutation}:${expected.boundary}: no publication, CAS, or reopen beyond the authorized boundary occurs`);
        } finally {
          removeFixture(root);
        }
      }
    }
  });

