          const result = await runFixtureExpressionAsync(root, `(async()=>{try{process.stdout.write(JSON.stringify({outcome:"returned",value:await m.p5cSObserveProgressRowTailAuthorityFixtureV1(${JSON.stringify(input)})}))}catch(error){process.stdout.write(JSON.stringify({outcome:"threw",message:String(error)}))}})()`);
          assert.equal(result.status, 0, result.stderr);
