    const durableValidationCall = new RegExp(`return\\s+(?:await\\s+)?${sharedPersistenceValidator}\\(\\s*\\{[\\s\\S]*recoveryState:\\s*input\\.recoveryState[\\s\\S]*recoveryOperationAuthority:\\s*input\\.recoveryOperationAuthority[\\s\\S]*ownerRows[\\s\\S]*reservationRows[\\s\\S]*expectedRunRows[\\s\\S]*activeRunRows[\\s\\S]*\\}\\s*\\)\\s*;`).exec(durableAuthority);
