        const original = seedExactOriginalPoisonStoreV1(root);
        const admitted = buildExactPoisonPublisherAdmissionFixtureV1(root, original);
        seedExactPoisonStrictChainFixtureV1(root, admitted.chain, "C");
        instrumentPhase5cSActiveRecoveryAdoptionFixtureV1(root);
        const operation = admitted.chain.records.successorOperation.value as Readonly<{ operationRef: string; operationHash: string }>;
        const successorRoot = realpathSync(path.join(original.store, admitted.chain.successorStoreRelativeRoot));
        const seeded = phase5cSSeedRecoveryAtRootFixtureV1(successorRoot, "A", "prepared");
        const databaseMaterials = terminalA["database-fence-reservations"] as Readonly<Record<string, Readonly<Record<string, unknown>>>>;
        const recoveryRoot = path.join(successorRoot, "recovery-source-bootstrap-v1");
        const immutableTarget = (kind: string, hash: string): string => path.join(recoveryRoot, "records", kind, "sha256", hash.slice(0, 2), `${hash}.json`);
        const sourceTarget = immutableTarget("terminal-source-runs", String(seeded.graph.terminalSource.terminalSourceRunHash));
        const runTarget = immutableTarget("terminal-run-launches", String(seeded.graph.terminalRun.terminalRunLaunchHash));
        const pairCloseTarget = path.join(successorRoot, "records", "source-run-launch-target-reservation-pair-closes", "sha256", String(seeded.graph.pairClose.targetReservationPairCloseHash).slice(0, 2), `${String(seeded.graph.pairClose.targetReservationPairCloseHash)}.json`);
