        terminalSourceRunHash: terminalStatus.terminalSourceRunHash,
        terminalRunLaunchRef: terminalStatus.terminalRunLaunchRef,
        terminalRunLaunchHash: terminalStatus.terminalRunLaunchHash,
        targetReservationPairCloseRef: terminalStatus.targetReservationPairCloseRef,
