        const successorStatus = immediateBytes === null ? null : JSON.parse(immediateBytes.toString("utf8")) as Readonly<{statusRef:string;statusHash:string}>;
        const successorPairBytes = successorStatus === null ? null : canonicalFixtureRecordV1(Object.freeze({ statusRef: successorStatus.statusRef, statusHash: successorStatus.statusHash }));
        const readyStatus = phase5cSCanonicalProgressStatusFixtureV1("ready");
