      const stable = await run("exact-final", expectedBytes, targetOnlyPolicy);
      const wrongBytes = await run("wrong-expected-bytes", Buffer.from("canonical-but-wrong\n", "utf8"), targetOnlyPolicy);
      writeFileSync(siblingPhysicalTarget, Buffer.from("allowed sibling\n", "utf8"), { mode: 0o600 });
      const allowedSibling = await run("allowed-sibling", expectedBytes, allowedSiblingPolicy);
      const foreignSibling = await run("foreign-sibling", expectedBytes, targetOnlyPolicy);
