      const faultTarget = path.join(authorityDirectory, path.basename(faultPhysicalTarget));
      symlinkSync(physicalTarget, faultPhysicalTarget);
      const partialOpenTree = filesystemTreeSnapshot(physicalDirectory);
      const partialOpenFault = await run("retained-member-partial-open-fault", expectedBytes, Object.freeze([family(target), family(siblingTarget), family(faultTarget)]));
      assert.deepEqual(filesystemTreeSnapshot(physicalDirectory), partialOpenTree, "partial member-open failure leaves the physical inventory untouched");
      unlinkSync(faultPhysicalTarget);
