      for (const count of [1, 7] as const) seed(postRename, `post-rename-incoming-q3-${count}`, "current", Object.freeze(Array.from({ length: count }, () => "current" as const)), true, Object.freeze({ state: "Q3", transition: "prior-to-current-cleanup", route: "current", requiresNormalization: true, row: postRename.row }), "terminal");
      seed(descriptor, "mixed-current-next", "current", Object.freeze(["current", "next"]), false, null, "terminal");
      seed(descriptor, "canonical-unequal", "current", Object.freeze(["unequal"]), false, null, "terminal");
      seed(descriptor, "crossed-candidate", "current", Object.freeze(["crossed"]), false, null, "terminal");
      seed(descriptor, "second-incomplete", "current", Object.freeze(["prefix-partial", "prefix-second"]), false, null, "terminal");
      seed(descriptor, "incoming-q3-over-cap", "current", Object.freeze(Array.from({ length: 8 }, () => "current" as const)), false, null, "prepared");
      seed(descriptor, "outgoing-q2-over-cap", "current", Object.freeze(Array.from({ length: 9 }, () => "next" as const)), false, null, "terminal");
      const retainedCatchup = PHASE5C_S_NONBLOCKED_ROWS_V1.find((entry) => entry.row === "migration_applying/consumed")!;
