        assert.equal(observed.descriptorDelta, 0, `${String(input.label)}: fixed/current and every Q member owner close on both retries`);
        assert.deepEqual(filesystemTreeSnapshot(String(input.successorRoot)), before, `${String(input.label)}: S-aware Q classification is physically read-only`);
