  it("P5c-S retains the physical current-status member and parent generation through the final classifier fence", async () => {
    const descriptor = PHASE5C_S_NONBLOCKED_ROWS_V1.find((entry) => entry.row === "migration_applying/consumed")!;
    const index = PHASE5C_S_NONBLOCKED_ROWS_V1.findIndex((entry) => entry.row === descriptor.row);
    const status = phase5cSCanonicalProgressStatusFixtureV1(descriptor.row);
    const previousStatus = phase5cSCanonicalProgressStatusFixtureV1(PHASE5C_S_NONBLOCKED_ROWS_V1[index - 1]!.row);
    const nextStatus = phase5cSCanonicalProgressStatusFixtureV1(descriptor.next!);
    const pairBytes = (value: Readonly<Record<string, unknown>>): Buffer => canonicalFixtureRecordV1(Object.freeze({ statusRef: value.statusRef, statusHash: value.statusHash }));
    for (const mutation of ["none", "member-aba", "parent-aba", "parent-open-race"] as const) {
      const root = createFixture();
      try {
        installExactCurrentSuccessorGitFixtureV1(root);
        instrumentPhase5cProgressFixtureV1(root);
        const successorRoot = path.join(root, `p5c-s-progress-q-${mutation}`);
        const operationHash = String(status.operationHash);
        const operationDirectory = path.join(successorRoot, "operations", "sha256", operationHash.slice(0, 2), operationHash);
        const target = path.join(operationDirectory, "01-current-status.pair.json");
        fixtureFile(root, path.relative(root, target), pairBytes(status), 0o600);
        const before = filesystemTreeSnapshot(successorRoot);
        const input = Object.freeze({
          target,
          evidence: "completed" as const,
          previousPairBytesBase64: pairBytes(previousStatus).toString("base64"),
          currentPairBytesBase64: pairBytes(status).toString("base64"),
          nextPairBytesBase64: pairBytes(nextStatus).toString("base64"),
          mutation,
        });
        const result = await runFixtureExpressionAsync(root, `(async()=>{const fs=await import("node:fs");const count=()=>fs.readdirSync("/dev/fd").filter((name)=>/^[0-9]+$/.test(name)).length;const before=count();try{const value=await m.p5cSObserveProgressQStabilityFixtureV1(${JSON.stringify(input)});process.stdout.write(JSON.stringify({outcome:"returned",value,descriptorDelta:count()-before}))}catch(error){process.stdout.write(JSON.stringify({outcome:"threw",message:String(error),descriptorDelta:count()-before}))}})()`);
        assert.equal(result.status, 0, result.stderr);
        const observed = JSON.parse(result.stdout) as Readonly<Record<string, unknown>>;
        assert.equal(observed.outcome, "returned", `${mutation}: copied physical S-aware classifier executes rather than a wrapper fallback: ${String(observed.message ?? "")}`);
        assert.equal(observed.descriptorDelta, 0, `${mutation}: the member and parent descriptors close on success and ABA refusal`);
        const value = observed.value as Readonly<Record<string, unknown>>;
        assert.equal(value.stableCalls, mutation === "parent-open-race" ? 0 : 1);
        assert.equal(value.closeCalls, mutation === "parent-open-race" ? 0 : 1, `${mutation}: a returned classifier owner closes once, while failed construction owns no returned close capability`);
        assert.equal(value.outcome, mutation === "none" ? "returned" : "threw", `${mutation}: only the unchanged member and parent generation remain selectable`);
        if (mutation === "none" || mutation === "parent-open-race") assert.deepEqual(filesystemTreeSnapshot(successorRoot), before, `${mutation}: the read-only current-status classifier leaves/restores the exact tree`);
        else assert.match(String(value.message), /current.status|member|parent|directory|identity|stable|changed/i, `${mutation}: the precise held physical authority reports the ABA refusal`);
        if (mutation === "parent-open-race") {
          assert.equal(value.mutationApplied, true, "parent-open-race: failure occurs after directory-chain acquisition but before parent identity transfer");
          assert.match(String(value.message), /ENOENT|no such file|parent|directory/i);
        }
      } finally {
        removeFixture(root);
      }
    }
  });

