            assert.equal(lstatSync(writerFixed, { bigint: true }).nlink, 2n, `${testCase.label}: A2 fixed writer retains its selected acquisition hardlink`);
            assert.equal(lstatSync(selected, { bigint: true }).ino, lstatSync(writerFixed, { bigint: true }).ino, `${testCase.label}: the matching stale owner is the exact selected fixed inode`);
