        assert.equal(result.status, 0, result.stderr);
        const observed = JSON.parse(result.stdout) as Readonly<Record<string, unknown>>;
        observations.push(Object.freeze({ authority: testCase.label, retained: testCase.authority === "retained", valid: testCase.valid, observed, treeStable: canonical(filesystemTreeSnapshot(successorRoot)) === canonical(before) }));
