      assert.equal(observed.outcome, "returned", `${authority}: copied classifier reaches its direct read-only authority boundary: ${String(observed.message ?? "")}`);
      assert.equal(observed.descriptorDelta, 0, `${authority}: classifier and any crossed retained owner close without descriptor leakage`);
      const value = observed.value as Readonly<Record<string, unknown>>;
      assert.deepEqual({ before: value.controllerHeldBefore, after: value.controllerHeldAfter }, { before: false, after: false }, `${authority}: selector classification acquires no controller mutation authority`);
      assert.equal(value.capabilitySize, 0, `${authority}: read-only classification neither strands nor consumes ambient retained authority`);
      assert.equal(value.retainedCapabilitySeen, entry.retained === true, `${authority}: exact retained same-process authority remains present and unconsumed through read-only classification: ${canonical(value)}`);
      assert.equal(value.outcome, entry.valid ? "returned" : "threw", `${authority}: only exact dead/reused or retained same-operation Q1 authority is selectable`);
      if (entry.valid) assert.deepEqual(
        { state: value.state, transition: value.transition, selectedRoute: value.selectedRoute, requiresNormalization: value.requiresNormalization, closeCalls: value.closeCalls },
        { state: "Q1", transition: "current-to-next", selectedRoute: "current", requiresNormalization: true, closeCalls: 1 },
        `${authority}: the bound incomplete successor remains current and carries normalization authority`,
      );
      else assert.match(String(value.message), /Q1|capability|writer|owner|pid|nonce|live|ambiguous|crossed|stale|bound|topology|fixed|selected/i);
      assert.equal(entry.treeStable, true, `${authority}: direct selector classification is physically read-only on acceptance and refusal`);
