  it("P5c-S preserves effect and owner primaries while controller release faults and clears all controller state", async () => {
    const cases = Object.freeze([
      Object.freeze({ label: "release-only", controllerFault: "clean", expected: /P5C_S_CONTROLLER_RELEASE_FAULT/ }),
      Object.freeze({ label: "effect-primary-over-release", controllerFault: "effect-and-release", expected: /P5C_S_CONTROLLER_EFFECT_FAULT/ }),
      Object.freeze({ label: "owner-primary-over-release", controllerFault: "owner-and-release", expected: /P5C_S_CONTROLLER_OWNER_CLOSE_FAULT/ }),
    ] as const);
    const failures: string[] = [];
    for (const testCase of cases) {
      const root = createFixture();
      try {
        const harness = configurePhase5cZeroProgressFixtureV1(root, true);
        instrumentPhase5cProgressResumeFixtureV1(root, true);
        const seeded = await runPhase5cZeroProgressFixtureV1(root, harness.observations, Object.freeze({ kind: "none" }), "prepare");
        assert.equal((JSON.parse(seeded.stdout) as Readonly<Record<string, unknown>>).outcome, "returned", `${testCase.label}: ${seeded.stderr}`);
        const operation = harness.admitted.chain.records.successorOperation.value as Readonly<{ operationRef: string; operationHash: string }>;
        const retained = phase5cSSeedRetainedReaderFixturesV1(root, operation);
        const before = filesystemTreeSnapshot(harness.original.store);
        const resumeProbe = Object.freeze({
          mode: "pre-schema",
          controllerFault: testCase.controllerFault,
          controllerReleaseFault: true,
          controllerReleaseFaultCalls: 0,
          authorization: retained.preSchema[0]!.body.authorization,
          restartAuthority: retained.preSchema[2]!.body.restartAuthority,
          terminal: retained.preSchema[5]!.body,
          controllerAcquireCalls: 0,
          controllerReleaseCalls: 0,
          controllerHeldAtAcquire: false,
          controllerHeldAfterRelease: true,
          controllerOperationDirectory: "",
          controllerArtifactsAfterRelease: Object.freeze([]),
          effectEntryCalls: 0,
          effectControllerHeld: false,
          plannedEffects: Object.freeze([]),
          ownerStableFaultCalls: 0,
          ownerCloseFaultCalls: 0,
        });
        const result = await runPhase5cZeroProgressFixtureV1(root, Object.freeze({ ...harness.observations, sResume: Object.freeze([resumeProbe]) }), Object.freeze({ kind: "none" }), "resume");
        try {
          assert.equal(result.status, 0, `${testCase.label}: ${result.stderr}`);
          const observed = JSON.parse(result.stdout) as Readonly<Record<string, unknown>>;
          assert.equal(observed.outcome, "threw", `${testCase.label}: selected resume propagates its first failure only after release cleanup`);
          assert.match(String(observed.message), testCase.expected, `${testCase.label}: the first effect/owner/release failure remains authoritative`);
          if (testCase.label !== "release-only") assert.doesNotMatch(String(observed.message), /P5C_S_CONTROLLER_RELEASE_FAULT/,
            `${testCase.label}: the later release close fault cannot replace the established primary`);
          const resume = observed.sResume as Readonly<Record<string, unknown>>;
          assert.deepEqual({
            controllerAcquireCalls: resume.controllerAcquireCalls,
            controllerReleaseCalls: resume.controllerReleaseCalls,
            controllerReleaseFaultCalls: resume.controllerReleaseFaultCalls,
            controllerHeldAtAcquire: resume.controllerHeldAtAcquire,
            controllerHeldAfterRelease: resume.controllerHeldAfterRelease,
            controllerArtifactsAfterRelease: resume.controllerArtifactsAfterRelease,
            descriptorDelta: observed.descriptorDelta,
          }, {
            controllerAcquireCalls: 1,
            controllerReleaseCalls: 1,
            controllerReleaseFaultCalls: 1,
            controllerHeldAtAcquire: true,
            controllerHeldAfterRelease: false,
            controllerArtifactsAfterRelease: [],
            descriptorDelta: 0,
          }, `${testCase.label}: release failure still closes physical ownership and clears active/WeakMap state exactly once`);
          assert.deepEqual(filesystemTreeSnapshot(harness.original.store), before,
            `${testCase.label}: paired failure cleanup leaves no status, controller, or writer residue`);
        } catch (error) {
          failures.push(`${testCase.label}: ${String(error)}`);
        }
      } finally {
        removeFixture(root);
      }
    }
    assert.deepEqual(failures, [], failures.join("\n"));
  });

