    const cas = Math.min(...["task12ReceiptExpectedPredecessorCasV1(", "task12CasCurrentStatusV1("].map((token) => {
      const index = advance.indexOf(token);
      return index < 0 ? Number.MAX_SAFE_INTEGER : index;
    }));
    const reopen = Math.min(...["resolveInternalProductionCurrentEntryAuthorityStatusWithSelectedCurrentEntryStoreContextV1(", "openExactPoisonPostVisibleProgressStatusV1("].map((token) => {
      const index = advance.indexOf(token);
      return index < 0 ? Number.MAX_SAFE_INTEGER : index;
    }));
    assert.ok(publish < cas && cas < reopen,
      "candidate content publication precedes its expected-predecessor current-status CAS and exact reopen");
    assert.match(advance.slice(0, cas), /candidate\.contentTarget[\s\S]*candidate\.contentBytes/);
    assert.match(advance.slice(cas, reopen), /candidate\.pairBytes/);
    assert.doesNotMatch(advance, /normalizeTask12CurrentStatusCasV1\(/,
      "the adjacent advance never repeats progress-Q normalization or exposes its pair before candidate content");
    assert.doesNotMatch(resume, /state\s*===\s*"terminal"[\s\S]*(?:readExactRetainedPreSchemaSpawnerRebindStatusV1|readExactRetainedMigration32StatusV1)/,
      "terminal composite authority is consumed by the owned raw pass and never re-read from an effect arm");

    const faultTypeStart = source.indexOf("type ExactPoisonPostVisibleProgressFaultBoundaryV1 =");
    const faultTypeEnd = source.indexOf(";", faultTypeStart) + 1;
    assert.ok(faultTypeStart >= 0 && faultTypeEnd > faultTypeStart, "S declares one private finite response-loss boundary union");
    const faultType = source.slice(faultTypeStart, faultTypeEnd);
    for (const boundary of PHASE5C_S_RETAINED_RESPONSE_BOUNDARIES_V1) {
      assert.match(faultType, new RegExp(`"${boundary}"`), `${boundary}: response loss is an exact private boundary`);
      assert.equal(source.split(`exactPoisonPostVisibleProgressFaultV1("${boundary}")`).length - 1, 1,
        `${boundary}: the inert fault seam is called exactly once after its real retained read or durable CAS`);
    }
    const assertRetainedBoundaryOrder = (
      label: string,
      locator: string,
      content: string,
      cas: string,
      locatorPattern: RegExp,
      contentPattern: RegExp,
    ): void => {
      const tokens = [
        `exactPoisonPostVisibleProgressFaultV1("before-${locator}")`,
        `exactPoisonPostVisibleProgressFaultV1("after-${locator}")`,
        `exactPoisonPostVisibleProgressFaultV1("before-${content}")`,
        `exactPoisonPostVisibleProgressFaultV1("after-${content}")`,
        `exactPoisonPostVisibleProgressFaultV1("before-${cas}")`,
        `exactPoisonPostVisibleProgressFaultV1("after-${cas}")`,
      ];
      const indexes = tokens.map((token) => source.indexOf(token));
      assert.ok(indexes.every((index) => index >= 0) && indexes.every((index, indexInList) => indexInList === 0 || index > indexes[indexInList - 1]!),
        `${label}: before/after locator, content, and CAS seams are lexically ordered around their owned actions`);
      assert.match(source.slice(indexes[0]!, indexes[1]!), locatorPattern,
        `${label}: locator boundary brackets exact pair open/compare and parent/member fence`);
      assert.match(source.slice(indexes[2]!, indexes[3]!), contentPattern,
        `${label}: content boundary brackets exported content-address resolver and canonical byte equality`);
      assert.match(source.slice(indexes[4]!, indexes[5]!), /(?:advanceTask12CurrentStatusV1|task12ReceiptExpectedPredecessorCasV1|task12CasCurrentStatusV1)\(/,
        `${label}: CAS boundary brackets the exact expected-predecessor status transition`);
    };
    for (const ordinal of ["00", "01", "02", "03", "04", "05"] as const) {
      assertRetainedBoundaryOrder(
        `pre-schema-${ordinal}`,
        `pre-schema-retained-locator-${ordinal}`,
        `pre-schema-retained-content-${ordinal}`,
        `pre-schema-retained-cas-${ordinal}`,
        /(?:authenticateTask12ReceiptDirectoryChainV1|openExactPoisonRecoveryMemberV1)[\s\S]*(?:assertExactPoisonRecoveryPinnedMemberStableV1|\.assertStable\(\))/,
        /resolveInternalProductionPreSchemaSpawnerRebindStatusV1[\s\S]*(?:canonicalComparable|canonicalRecordBytes|Buffer\.equals|\.equals\()/,
      );
    }
    for (const step of [Object.freeze({ ordinal: "01", cas: "consumed" }), Object.freeze({ ordinal: "02", cas: "receipt" })] as const) {
      assertRetainedBoundaryOrder(
        `migration-${step.ordinal}`,
        `migration-retained-locator-${step.ordinal}`,
        `migration-retained-content-${step.ordinal}`,
        `migration-retained-cas-${step.cas}`,
        /(?:authenticateTask12ReceiptDirectoryChainV1|openExactPoisonRecoveryMemberV1)[\s\S]*(?:assertExactPoisonRecoveryPinnedMemberStableV1|\.assertStable\(\))/,
        /resolveInternalProductionPreManifestMigration32AuthorizationStatusV1[\s\S]*(?:canonicalComparable|canonicalRecordBytes|Buffer\.equals|\.equals\()/,
      );
    }
    const auditBefore = source.indexOf('exactPoisonPostVisibleProgressFaultV1("before-migration-current-audit-publication")');
    const auditAfter = source.indexOf('exactPoisonPostVisibleProgressFaultV1("after-migration-current-audit-publication")');
    const auditCasBefore = source.indexOf('exactPoisonPostVisibleProgressFaultV1("before-migration-retained-cas-current-audited")');
    const auditCasAfter = source.indexOf('exactPoisonPostVisibleProgressFaultV1("after-migration-retained-cas-current-audited")');
    assert.ok(auditBefore >= 0 && auditAfter > auditBefore && auditCasBefore > auditAfter && auditCasAfter > auditCasBefore,
      "migration audit publication is durably bracketed before its current-audited CAS");
    assert.match(source.slice(auditBefore, auditAfter), /publishTask12HashedRecordV1\(\s*"current-audits"[\s\S]*(?:resolveInternalProductionBootstrapHandoffCurrentAuditV1|openExactPoisonRecoveryMemberV1|assertStable)/,
      "audit response boundary owns exact content publication and stable reopen/authentication");
    assert.match(source.slice(auditCasBefore, auditCasAfter), /(?:advanceTask12CurrentStatusV1|task12ReceiptExpectedPredecessorCasV1|task12CasCurrentStatusV1)\(/,
      "current-audited response boundary owns exactly the adjacent expected-predecessor CAS");
    assert.equal([...faultType.matchAll(/"(?:before|after)-(?:pre-schema|migration)-[^"]+"/g)].length, PHASE5C_S_RETAINED_RESPONSE_BOUNDARIES_V1.length,
      "S has no ambient or unnamed retained response-loss boundary");
    const faultHook = topLevelFunctionRegionV1(source, "exactPoisonPostVisibleProgressFaultV1");
    assert.match(faultHook, /^function exactPoisonPostVisibleProgressFaultV1\(_boundary:\s*ExactPoisonPostVisibleProgressFaultBoundaryV1\):\s*void\s*\{\s*\}$/,
      "the private production response-loss seam is inert");
    assert.equal(/^export\s+.*exactPoisonPostVisibleProgressFaultV1/m.test(source), false);
